package book

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package book 是本地行情、仓位与风险的本地基线。
package book

// Ready 表示基线可以运行。
func Ready() bool { return true }

